css:
.d-ea{width:220px;padding:14px;text-align:center;border:1px dashed var(--line);border-radius:10px}
.d-ea svg{width:80px;height:54px}
.d-ea b{display:block;font-size:12.5px;margin:2px 0}
.d-ea p{margin:0 0 10px;font-size:11px;color:var(--muted)}
.d-btn{font:inherit;font-size:13px;padding:8px 16px;border-radius:10px;border:1px solid var(--line);background:var(--paper);color:var(--ink);cursor:pointer;transition:transform .16s var(--ease),background-color .16s,color .16s,border-color .16s}
.d-btn:hover{box-shadow:0 6px 18px #20241e14}
.d-btn:active{transform:scale(.97)}
.d-btn.d-btn-primary{background:var(--ink);color:var(--paper);border-color:var(--ink)}
